// Crash-recovery journal. Pure node (no 'electron' import): every function takes
// the journal directory explicitly so it can be unit tested.
//
// Layout: <dir>/<docId>.json = { docId, path, contents, savedAt }
// Corrupt journals are moved to <dir>/corrupt/ so they never block startup.
import { promises as fs } from 'fs'
import { join } from 'path'
import { atomicWrite } from './fileio'

export type Journal = {
  docId: string
  path: string | null
  contents: string
  savedAt: number
}

// docIds are generated by main (UUIDs); still guard against path tricks.
const SAFE_ID = /^[A-Za-z0-9_-]{1,128}$/

function journalFile(dir: string, docId: string): string {
  if (!SAFE_ID.test(docId)) throw new Error(`invalid docId: ${docId}`)
  return join(dir, `${docId}.json`)
}

export async function writeJournal(
  dir: string,
  entry: { docId: string; path: string | null; contents: string },
  now: number = Date.now()
): Promise<void> {
  const file = journalFile(dir, entry.docId)
  await fs.mkdir(dir, { recursive: true })
  const journal: Journal = {
    docId: entry.docId,
    path: entry.path,
    contents: entry.contents,
    savedAt: now
  }
  await atomicWrite(file, JSON.stringify(journal))
}

export async function deleteJournal(dir: string, docId: string): Promise<void> {
  if (!SAFE_ID.test(docId)) return
  await fs.rm(journalFile(dir, docId), { force: true })
}

function isJournal(v: unknown, expectedId: string): v is Journal {
  if (!v || typeof v !== 'object') return false
  const j = v as Record<string, unknown>
  return (
    j.docId === expectedId &&
    (j.path === null || typeof j.path === 'string') &&
    typeof j.contents === 'string' &&
    typeof j.savedAt === 'number'
  )
}

/**
 * Return all valid journals in `dir` (oldest first). Unparseable or invalid
 * files are moved into `<dir>/corrupt/`. Never throws for a missing dir.
 */
export async function scanJournals(dir: string): Promise<Journal[]> {
  let names: string[]
  try {
    names = await fs.readdir(dir)
  } catch {
    return []
  }
  const out: Journal[] = []
  for (const name of names) {
    if (!name.endsWith('.json')) continue
    const docId = name.slice(0, -'.json'.length)
    const file = join(dir, name)
    try {
      const st = await fs.stat(file)
      if (!st.isFile()) continue
      const parsed: unknown = JSON.parse(await fs.readFile(file, 'utf8'))
      if (!SAFE_ID.test(docId) || !isJournal(parsed, docId)) throw new Error('invalid journal')
      out.push(parsed)
    } catch {
      await quarantine(dir, name)
    }
  }
  out.sort((a, b) => a.savedAt - b.savedAt)
  return out
}

async function quarantine(dir: string, name: string): Promise<void> {
  try {
    const corruptDir = join(dir, 'corrupt')
    await fs.mkdir(corruptDir, { recursive: true })
    await fs.rename(join(dir, name), join(corruptDir, `${Date.now()}-${name}`))
  } catch {
    // Last resort: ignore. Startup must not crash on a bad journal.
  }
}
